export const DEFAULT_EXCLUDED_DIRS = [
  'node_modules',
  '.git',
  '.venv',
  '__pycache__',
  '.idea',
  '.vscode',
  'dist',
  'build'
];

export const DEFAULT_CODE_EXTENSIONS = [
  '.py',
  '.ipynb',
  '.js',
  '.ts',
  '.jsx',
  '.tsx',
  '.r',
  '.rmd',
  '.java',
  '.scala'
];

export const DEFAULT_AI_LIBRARIES = [
  // Python ML/AI libraries
  'sklearn',
  'scikit-learn',
  'tensorflow',
  'torch',
  'pytorch',
  'keras',
  'xgboost',
  'lightgbm',
  'catboost',
  'transformers',
  'huggingface',
  'spacy',
  'nltk',
  'gensim',
  'fastai',
  'opencv',
  'cv2',
  // JavaScript ML/AI libraries
  '@tensorflow',
  'ml5',
  'brain.js',
  'synaptic',
  '@huggingface',
  // R packages
  'caret',
  'randomForest',
  'kernlab',
  'nnet',
  'rpart'
];

export const DEFAULT_AI_FUNCTIONS = [
  // Training/fitting
  'fit',
  'train',
  'fit_transform',
  'compile',
  // Prediction/inference
  'predict',
  'transform',
  'inference',
  'forward',
  // Evaluation
  'score',
  'evaluate',
  'accuracy_score',
  'classification_report',
  // Data preparation
  'preprocessing',
  'tokenize',
  'encode',
  'normalize',
  // Fine-tuning / generative
  'generate',
  'fine_tune',
  'finetune'
];
import {
  DEFAULT_AI_FUNCTIONS,
  DEFAULT_AI_LIBRARIES
} from './constants.js';

const uniqPush = (store, key, value) => {
  const list = store[key] || (store[key] = []);
  if (!list.includes(value)) {
    list.push(value);
  }
};

export const createLibraryDetector = (libraries = DEFAULT_AI_LIBRARIES) => ({
  id: 'libraries',
  analyze({ content, filePath, result }) {
    for (const library of libraries) {
      const regex = new RegExp(`(import|from|require\\s*\\(\\s*['"\`])\\s*${library}`, 'i');
      if (regex.test(content)) {
        uniqPush(result.aiLibraryMatches, filePath, library);
        result.markAiFile(filePath);
      }
    }
  }
});

export const createFunctionDetector = (functions = DEFAULT_AI_FUNCTIONS) => ({
  id: 'functions',
  analyze({ content, filePath, result }) {
    for (const func of functions) {
      const regex = new RegExp(`[\\s\\.\\(]${func}\\s*\\(`, 'g');
      if (regex.test(content)) {
        uniqPush(result.aiFunctionMatches, filePath, func);
        result.markAiFile(filePath);
      }
    }
  }
});

export const DEFAULT_DETECTORS = [
  createLibraryDetector(),
  createFunctionDetector()
];
import fs from 'fs';
import path from 'path';

import {
  DEFAULT_CODE_EXTENSIONS,
  DEFAULT_EXCLUDED_DIRS
} from './constants.js';
import { DEFAULT_DETECTORS } from './detectors.js';

const defaultConfig = {
  root: process.cwd(),
  excludedDirs: DEFAULT_EXCLUDED_DIRS,
  extensions: DEFAULT_CODE_EXTENSIONS,
  detectors: DEFAULT_DETECTORS,
  fs
};

const shouldSkip = (name, excluded) => excluded.includes(name);

const createResult = () => {
  const result = {
    aiFiles: [],
    totalFiles: 0,
    aiLibraryMatches: {},
    aiFunctionMatches: {}
  };

  const aiSet = new Set();
  result.markAiFile = (filePath) => {
    if (!aiSet.has(filePath)) {
      aiSet.add(filePath);
      result.aiFiles.push(filePath);
    }
  };

  return result;
};

export function scanCodebase(options = {}) {
  const config = { ...defaultConfig, ...options };
  const {
    root,
    excludedDirs,
    extensions,
    detectors,
    fs: fsModule
  } = config;

  const result = createResult();

  function scanDirectory(dir) {
    let entries;
    try {
      entries = fsModule.readdirSync(dir, { withFileTypes: true });
    } catch (error) {
      console.error(`Error scanning directory ${dir}: ${error.message}`);
      return;
    }

    for (const entry of entries) {
      if (shouldSkip(entry.name, excludedDirs)) continue;

      const fullPath = path.join(dir, entry.name);

      if (entry.isDirectory()) {
        scanDirectory(fullPath);
      } else if (entry.isFile()) {
        const ext = path.extname(entry.name).toLowerCase();
        if (!extensions.includes(ext)) continue;

        result.totalFiles += 1;
        let content;
        try {
          content = fsModule.readFileSync(fullPath, 'utf8');
        } catch (error) {
          console.error(`Error reading file ${fullPath}: ${error.message}`);
          continue;
        }

        for (const detector of detectors) {
          try {
            detector.analyze({
              filePath: fullPath,
              content,
              result,
              config
            });
          } catch (error) {
            console.error(`Detector ${detector.id || 'unknown'} failed on ${fullPath}: ${error.message}`);
          }
        }
      }
    }
  }

  scanDirectory(root);

  return {
    aiFiles: result.aiFiles,
    totalFiles: result.totalFiles,
    aiLibraryMatches: result.aiLibraryMatches,
    aiFunctionMatches: result.aiFunctionMatches
  };
}

export function createScanner(config = {}) {
  return (overrides = {}) => scanCodebase({ ...config, ...overrides });
}

export { DEFAULT_DETECTORS } from './detectors.js';
export {
  DEFAULT_CODE_EXTENSIONS,
  DEFAULT_EXCLUDED_DIRS
} from './constants.js';
import fs from 'fs';
import os from 'os';
import path from 'path';
import { describe, expect, it } from 'vitest';
import { fileURLToPath } from 'url';

import { createScanner, scanCodebase } from './index.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const EXAMPLES_DIR = path.resolve(__dirname, '../../../../examples');

describe('scanCodebase', () => {
  it('detects AI libraries and functions in example projects', () => {
    const results = scanCodebase({ root: EXAMPLES_DIR });

    expect(results.totalFiles).toBeGreaterThan(0);
    expect(results.aiFiles.length).toBeGreaterThan(0);

    const libraryMatches = Object.values(results.aiLibraryMatches).flat();
    expect(libraryMatches.some((lib) => lib.includes('tensorflow'))).toBe(true);
  });

  it('supports custom detectors via createScanner', () => {
    const detectorInvocations = [];
    const customScanner = createScanner({
      detectors: [
        {
          id: 'custom',
          analyze({ filePath, content, result }) {
            if (content.includes('model')) {
              result.markAiFile(filePath);
              detectorInvocations.push(filePath);
            }
          }
        }
      ]
    });

    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-scan-'));
    const filePath = path.join(tmpDir, 'mock.js');
    fs.writeFileSync(filePath, 'const model = {};');

    const results = customScanner({ root: tmpDir, extensions: ['.js'] });

    expect(results.aiFiles).toContain(filePath);
    expect(detectorInvocations).toContain(filePath);

    fs.rmSync(tmpDir, { recursive: true, force: true });
  });
});
import path from "node:path";

import { DynamicStructuredTool } from "langchain/tools";
import { z } from "zod";

import { Scanners } from "frai-core";

import { resolveWorkingDirectory } from "../config/env.js";

const schema = z.object({
  root: z
    .string()
    .describe("Optional path to scan. Defaults to the current working directory.")
    .optional()
});

export const scanRepositoryTool = new DynamicStructuredTool({
  name: "scan_repository",
  description:
    "Scan a codebase for AI indicators using FRAI's static detectors. Provide a relative path when scanning outside the current working directory.",
  schema,
  func: async ({ root }) => {
    const cwd = resolveWorkingDirectory(root);
    const result = Scanners.scanCodebase({ root: cwd });

    const aiFiles = result.aiFiles.map((file) => path.relative(cwd, file));
    // aiLibraryMatches structure: { [filePath]: [library1, library2, ...] }
    // We need to invert it to { [library]: [filePath1, filePath2, ...] }
    const libraryMap: Record<string, string[]> = {};
    for (const [filePath, libraries] of Object.entries(result.aiLibraryMatches)) {
      const relativePath = path.relative(cwd, filePath);
      for (const library of libraries as string[]) {
        if (!libraryMap[library]) {
          libraryMap[library] = [];
        }
        libraryMap[library].push(relativePath);
      }
    }
    const libraryMatches = Object.entries(libraryMap).map(([library, files]) => ({
      library,
      files
    }));

    const summary = [
      `Scanned ${result.totalFiles} source files.`,
      aiFiles.length
        ? `Detected ${aiFiles.length} AI-indicative files: ${aiFiles.join(", ")}.`
        : "No AI-indicative files detected.",
      libraryMatches.length
        ? `Library matches: ${libraryMatches
            .map(({ library, files }) => `${library} (${files.join(", ")})`)
            .join("; ")}.`
        : "No flagged AI libraries detected."
    ];

    return summary.join(" ");
  }
});
