  let inTemplate = false;
  // Brace depth at which each open `${` template expression started.
  const templateStack = [];

  while (i < source.length) {
    const ch = source[i];
    const next = source[i + 1];

    if (inTemplate) {
      if (ch === '\\') {
        out += source.slice(i, i + 2);
        i += 2;
      } else if (ch === '`') {
        out += ch;
        inTemplate = false;
        i += 1;
      } else if (ch === '$' && next === '{') {
        out += '${';
